# cuBLASLt FP32 host-scalar path. Layout/operation attributes are allowlisted.
add('cublasLtCreate',B,'cublasLtHandle_t *handle','if(!handle) BAD;AFTER(*handle=(cublasLtHandle_t)(uintptr_t)GET(0));','cublasLtHandle_t h;rc=cublasLtCreate(&h);if(!rc)rc=save_object(LT,h,out);')
for suffix,typ,kind in [('','cublasLtHandle_t','LT'),('MatrixLayout','cublasLtMatrixLayout_t','LAYOUT'),('MatmulDesc','cublasLtMatmulDesc_t','MATMUL'),('MatmulPreference','cublasLtMatmulPreference_t','PREF')]:
 add('cublasLt'+suffix+'Destroy',B,typ+' desc','PUT(0,desc);',f'OBJ(0,{kind},d);rc=cublasLt{suffix}Destroy(d);if(!rc)drop_object(A(0));')
add('cublasLtMatrixLayoutCreate',B,'cublasLtMatrixLayout_t *desc,cudaDataType type,uint64_t rows,uint64_t cols,int64_t ld',
 'if(!desc) BAD;PUT(0,type);PUT(1,rows);PUT(2,cols);PUT(3,ld);AFTER(*desc=(cublasLtMatrixLayout_t)(uintptr_t)GET(0));',
 'if(A(0)!=CUDA_R_32F) UNSUP;size_t bytes;if(!layout_bytes(A(1),A(2),A(3),&bytes)) BAD;cublasLtMatrixLayout_t d;rc=cublasLtMatrixLayoutCreate(&d,A(0),A(1),A(2),A(3));if(!rc){rc=save_object(LAYOUT,d,out);if(!rc)object_size(vmweave_get(out,8),bytes);}')
add('cublasLtMatmulDescCreate',B,'cublasLtMatmulDesc_t *desc,cublasComputeType_t compute,cudaDataType_t scale',
 'if(!desc) BAD;PUT(0,compute);PUT(1,scale);AFTER(*desc=(cublasLtMatmulDesc_t)(uintptr_t)GET(0));',
 'if((A(0)!=CUBLAS_COMPUTE_32F&&A(0)!=CUBLAS_COMPUTE_32F_PEDANTIC)||A(1)!=CUDA_R_32F) UNSUP;cublasLtMatmulDesc_t d;rc=cublasLtMatmulDescCreate(&d,A(0),A(1));if(!rc)rc=save_object(MATMUL,d,out);')
add('cublasLtMatmulPreferenceCreate',B,'cublasLtMatmulPreference_t *desc','if(!desc) BAD;AFTER(*desc=(cublasLtMatmulPreference_t)(uintptr_t)GET(0));','cublasLtMatmulPreference_t d;rc=cublasLtMatmulPreferenceCreate(&d);if(!rc)rc=save_object(PREF,d,out);')
add('cublasLtMatmulDescSetAttribute',B,'cublasLtMatmulDesc_t desc,cublasLtMatmulDescAttributes_t attr,const void *value,size_t bytes',
 'if(!value||bytes>8) BAD;PUT(0,desc);PUT(1,attr);PUT(2,bytes);if(attr==CUBLASLT_MATMUL_DESC_BIAS_POINTER){if(bytes!=sizeof(void*)) BAD;void *v;memcpy(&v,value,sizeof(v));REF(4,v,0);}else memcpy(p+32,value,bytes);',
 'OBJ(0,MATMUL,d);size_t bytes=A(2);if(A(1)==CUBLASLT_MATMUL_DESC_BIAS_POINTER){if(bytes!=sizeof(void*)) BAD;DEV(4,0,1,bias);rc=cublasLtMatmulDescSetAttribute(d,A(1),&bias,sizeof(bias));if(!rc){int i=object_index(A(0));objects[i].ref=(struct vmweave_device_ref){A(4),A(5)};}}else {if(!lt_attribute(A(1),bytes,p+32)) UNSUP;rc=cublasLtMatmulDescSetAttribute(d,A(1),p+32,bytes);}')
add('cublasLtMatmulPreferenceSetAttribute',B,'cublasLtMatmulPreference_t desc,cublasLtMatmulPreferenceAttributes_t attr,const void *value,size_t bytes',
 'if(!value||bytes>8) BAD;PUT(0,desc);PUT(1,attr);PUT(2,bytes);memcpy(p+32,value,bytes);',
 'OBJ(0,PREF,d);if(!lt_preference(A(1),A(2))) UNSUP;rc=cublasLtMatmulPreferenceSetAttribute(d,A(1),p+32,A(2));')
add('cublasLtMatmulAlgoGetHeuristic',B,'cublasLtHandle_t handle,cublasLtMatmulDesc_t desc,cublasLtMatrixLayout_t ad,cublasLtMatrixLayout_t bd,cublasLtMatrixLayout_t cd,cublasLtMatrixLayout_t dd,cublasLtMatmulPreference_t pref,int count,cublasLtMatmulHeuristicResult_t results[],int *returned',
 'if(count<1||count>4||!results||!returned) BAD;PUT(0,handle);PUT(1,desc);PUT(2,ad);PUT(3,bd);PUT(4,cd);PUT(5,dd);PUT(6,pref);PUT(7,count);AFTER(*returned=GET(0);if(*returned<0||*returned>count) BAD;memcpy(results,out+16,*returned*sizeof(*results)));',
 'LT_HANDLE(0,h);OBJ(1,MATMUL,d);OBJ(2,LAYOUT,ad);OBJ(3,LAYOUT,bd);OBJ(4,LAYOUT,cd);OBJ(5,LAYOUT,dd);OBJ(6,PREF,pref);int count=A(7),returned=0;if(count<1||count>4||16+count*sizeof(cublasLtMatmulHeuristicResult_t)>VMWEAVE_LIBRARY_RESPONSE) BAD;cublasLtMatmulHeuristicResult_t results[4]={0};rc=cublasLtMatmulAlgoGetHeuristic(h,d,ad,bd,cd,dd,pref,count,results,&returned);if(!rc){if(returned<0||returned>count) BAD;OUT(0,returned);memcpy(out+16,results,returned*sizeof(*results));}')
add('cublasLtMatmul',B,'cublasLtHandle_t handle,cublasLtMatmulDesc_t desc,const void *alpha,const void *a,cublasLtMatrixLayout_t ad,const void *b,cublasLtMatrixLayout_t bd,const void *beta,const void *c,cublasLtMatrixLayout_t cd,void *d,cublasLtMatrixLayout_t dd,const cublasLtMatmulAlgo_t *algo,void *workspace,size_t bytes,cudaStream_t stream',
 'if(!alpha||!beta) BAD;PUT(0,handle);PUT(1,desc);PUT(2,ad);PUT(3,bd);PUT(4,cd);PUT(5,dd);PUT(6,bytes);PUT(7,stream);PUT(8,algo!=NULL);memcpy(p+72,alpha,4);memcpy(p+80,beta,4);REF(11,a,0);REF(13,b,0);REF(15,c,0);REF(17,d,0);REF(19,workspace,bytes);if(algo)memcpy(p+512,algo,sizeof(*algo));',
 'LT_HANDLE(0,h);OBJ(1,MATMUL,desc);OBJ(2,LAYOUT,ad);OBJ(3,LAYOUT,bd);OBJ(4,LAYOUT,cd);OBJ(5,LAYOUT,dd);STREAM(7,st);DEV(11,object_bytes(A(2)),0,a);DEV(13,object_bytes(A(3)),0,b);DEV(15,object_bytes(A(4)),0,c);DEV(17,object_bytes(A(5)),0,d);DEV(19,A(6),A(6)==0,ws);float alpha,beta;memcpy(&alpha,p+72,4);memcpy(&beta,p+80,4);if(!check_bias(s,A(1),dd)) BAD;cublasLtMatmulAlgo_t algo;memcpy(&algo,p+512,sizeof(algo));rc=cublasLtMatmul(h,desc,&alpha,a,ad,b,bd,&beta,c,cd,d,dd,A(8)?&algo:NULL,ws,A(6),st);')
